import React from 'react';
import { FaSignal } from 'react-icons/fa';
import '../styles/CourseCard.css';

const CourseCard = ({ image, title, description, level = "BEGINNER", onEnroll }) => {
    return (
        <div className="modern-course-card">
            <div className="card-image-container">
                <img src={image} alt={title} className="card-top-image" />
            </div>
            <div className="card-info">
                <span className="course-type">COURSE</span>
                <h3 className="card-course-title">{title}</h3>
                <p className="card-course-desc">{description}</p>
                <div className="card-footer-box">
                    <div className="level-badge">
                        <FaSignal className="signal-icon" />
                        <span>{level}</span>
                    </div>
                </div>
                <button className="enroll-card-btn" onClick={() => onEnroll(title)}>
                    Enroll Now
                </button>
            </div>
        </div>
    );
};

export default CourseCard;
